from h import *
O=[]
O.append(R(6541800,
ar=("سلطة البرتقال الدموي (Insalata D’ Arrance Sangouse)","تشتهر صقلية ببساتين البرتقال الجميلة الخصبة التي تنتج بعضًا من أكثر أنواع البرتقال عطرًا في العالم. أدخل العرب أشجار البرتقال إلى الجزيرة خلال فترة حكمهم لها، وقد ازدهرت في الرماد البركاني عند سفح جبل إتنا. ابحث عن أحلى برتقال ممكن لهذه الوصفة. وإن استطعت، فاستخدم البرتقال الدموي الصقلي؛ فلونه الأحمر يضفي طابعًا احتفاليًا على هذه السلطة الفاخرة.","6","½ كوب",
["4 حبات برتقال دموي كاملة (حوالي رطل واحد في المجموع، مقشرة ومقطعة إلى شرائح دائرية)","2 ساق بصل أخضر (مفرومة ناعمًا)","¼ كوب عصير برتقالة واحدة","2 ملعقة كبيرة زيت زيتون بكر ممتاز (يفضل المعصور على البارد أولًا وغير المصفى)","¼ ملعقة صغيرة ملح بحري غير مكرر","¼ ملعقة صغيرة فلفل أسود (مطحون طازجًا)","⅛ ملعقة صغيرة رقائق الفلفل الأحمر الحار المجروشة"],
["ضع شرائح البرتقال على طبق كبير ووزّع البصل الأخضر فوقها.","في وعاء صغير، اخفق عصير البرتقال وزيت الزيتون معًا، وتبّل بالملح والفلفل ورقائق الفلفل الأحمر الحار المجروشة. رشّه فوق السلطة وقدّمها فورًا."],[],[])))
O.append(R(6543489,
es=("Dip de requesón batido","El dip de requesón batido es una alternativa ligera y cremosa a los dips tradicionales y ofrece una opción rica en proteínas para picar. ¡Disfrútelo con sus verduras favoritas, como brócoli, pimiento morrón, zanahorias y más!","4","1/3 de taza",
["1 taza de requesón (bajo en grasa)","2 cucharadas de yogur griego natural sin grasa","1 cucharada de jugo de limón","2 cucharaditas de salsa Worcestershire","1 diente de ajo (picado)","1 cucharada de cebollino fresco (picado)","1/4 de cucharadita de pimienta negra"],
["En una licuadora o procesador de alimentos, combine el requesón bajo en grasa, el yogur griego, el jugo de limón fresco, la salsa Worcestershire y el ajo picado. Licúe los ingredientes hasta obtener una consistencia suave y cremosa. Esto puede tardar unos minutos, según la potencia de su licuadora o procesador de alimentos.","Cuando la mezcla esté suave, páselo a un tazón. Agregue el cebollino fresco picado y sazone el dip de requesón batido con la pimienta. Mezcle bien para que los sabores se distribuyan de manera uniforme.","Refrigere el dip durante al menos 30 minutos antes de servir para que los sabores se integren y realcen el sabor general."],[],[]),
ar=("غموس الجبن القريش المخفوق","غموس الجبن القريش المخفوق بديل خفيف وكريمي للغموس التقليدي، ويوفر خيارًا غنيًا بالبروتين للتسلية بين الوجبات. استمتع به مع خضارك المفضلة مثل البروكلي والفلفل الرومي والجزر وغيرها!","4","⅓ كوب",
["1 كوب جبن قريش (قليل الدسم)","2 ملعقة كبيرة زبادي يوناني سادة خالٍ من الدسم","1 ملعقة كبيرة عصير ليمون","2 ملعقة صغيرة صلصة ورسيستر","1 فص ثوم (مفروم)","1 ملعقة كبيرة ثوم معمر طازج (مفروم)","¼ ملعقة صغيرة فلفل أسود"],
["في خلاط أو محضّرة طعام، اخلط الجبن القريش قليل الدسم والزبادي اليوناني وعصير الليمون الطازج وصلصة ورسيستر والثوم المفروم. اخلط المكونات حتى تحصل على قوام ناعم وكريمي. قد يستغرق ذلك بضع دقائق بحسب قوة الخلاط أو محضّرة الطعام.","عندما يصبح الخليط ناعمًا، انقله إلى وعاء. أضف الثوم المعمر الطازج المفروم وتبّل غموس الجبن القريش المخفوق بالفلفل. اخلط جيدًا لتتوزع النكهات بالتساوي.","ضع الغموس في الثلاجة لمدة 30 دقيقة على الأقل قبل التقديم لتمتزج النكهات ويتحسن الطعم العام."],[],[])))
O.append(R(6545397,
es=("Estrogonoff de res","Prepare un plato sustancioso y sabroso que seguramente satisfará sus antojos y, al mismo tiempo, ayudará a mantener sus niveles de glucosa en la sangre (azúcar en la sangre) bajo control. Aprenda paso a paso cómo preparar una salsa cremosa y sabrosa combinada con carne de res magra e ingredientes saludables, lo que hace que este plato sea delicioso y, a la vez, cuidadoso con su salud. Ya sea que cocine para usted o para sus seres queridos, esta receta seguramente se convertirá en un básico de su cocina.","5","1/5 de la receta",
["5 oz de fideos de huevo integrales (sin cocinar)","1 cucharadita de aceite de oliva","1 libra de filete de res (sin grasa visible, cortado en tiras de 2 pulgadas)","1 1/2 tazas de champiñones blancos (en rebanadas)","1/2 cebolla mediana (picada fina)","1 cucharada de harina de trigo para todo uso","1/4 de taza de agua","1 cucharadita de mostaza Dijon","14 1/2 oz de caldo de res sin grasa y sin sal añadida","1/2 taza de crema agria sin grasa","1/4 de cucharadita de pimienta negra"],
["Cocine los fideos según las instrucciones del paquete, omitiendo la sal.","Agregue el aceite a una sartén grande a fuego alto. Agregue la carne y saltee durante unos 3 minutos. Retire la carne de la sartén. Agregue los champiñones y la cebolla y saltee durante 5 minutos o hasta que comiencen a dorarse.","Agregue la harina y cocine durante 1 minuto. Agregue el agua con cuidado para desglasar la sartén; cocine durante 2 minutos. Agregue la mostaza Dijon y el caldo de res; deje que hierva. Reduzca el fuego y cocine a fuego lento durante 5 minutos.","Vuelva a agregar la carne y los jugos que haya soltado al caldo y cocine a fuego lento 3 minutos más. Agregue la crema agria y la pimienta; cocine a fuego lento durante 30 segundos.","Sirva sobre los fideos de huevo integrales."],[],[]),
ar=("بيف ستروغانوف","حضّر طبقًا مشبعًا ولذيذًا من المؤكد أنه سيشبع رغباتك مع المساعدة على إبقاء مستويات الغلوكوز (سكر الدم) تحت السيطرة. تعلّم خطوة بخطوة كيف تصنع صلصة كريمية شهية مع لحم بقر قليل الدسم ومكونات صحية، مما يجعل هذا الطبق لذيذًا ومراعيًا لصحتك في الوقت نفسه. سواء كنت تطبخ لنفسك أو لأحبائك، فمن المؤكد أن هذه الوصفة ستصبح أساسية في مطبخك.","5","1/5 من الوصفة",
["5 أونصة نودلز بيض من الحبوب الكاملة (غير مطبوخة)","1 ملعقة صغيرة زيت زيتون","1 رطل فيليه لحم بقر (بدون دهون ظاهرة، مقطع إلى شرائح بطول 2 بوصة)","1½ كوب فطر أبيض (شامبينيون) (مقطع إلى شرائح)","½ حبة بصل متوسطة (مفرومة ناعمًا)","1 ملعقة كبيرة دقيق متعدد الاستخدامات","¼ كوب ماء","1 ملعقة صغيرة خردل ديجون","14½ أونصة مرق لحم بقر خالٍ من الدسم وبدون ملح مضاف","½ كوب كريمة حامضة خالية من الدسم","¼ ملعقة صغيرة فلفل أسود"],
["اطهِ النودلز وفق تعليمات العبوة، مع الاستغناء عن الملح.","أضف الزيت إلى مقلاة تسوية كبيرة على نار عالية. أضف اللحم وسوّطه لمدة 3 دقائق تقريبًا. أخرج اللحم من المقلاة. أضف الفطر والبصل وسوّطهما لمدة 5 دقائق أو حتى يبدآن بالتحمير.","أضف الدقيق واطهِ لمدة دقيقة واحدة. أضف الماء برفق لإذابة بقايا القاع في المقلاة؛ واطهِ لمدة دقيقتين. أضف خردل ديجون ومرق اللحم؛ واتركه حتى يغلي. اخفض الحرارة واتركه على نار هادئة لمدة 5 دقائق.","أعد اللحم وما خرج منه من عصارة إلى المرق واتركه على نار هادئة 3 دقائق إضافية. أضف الكريمة الحامضة والفلفل؛ واتركه على نار هادئة لمدة 30 ثانية.","قدّمه فوق نودلز البيض من الحبوب الكاملة."],[],[])))
O.append(R(6545769,
ar=("خليط وجبة خفيفة صحي — وصفة للأذواق الرفيعة","هذا الخليط الخفيف مليء بالتغذية والدهون الصحية من المكسرات والبذور العديدة. بالإضافة إلى ذلك، يضيف التوت الأزرق المجفف بالتجميد نكهة حامضة تشبه الفاكهة إلى الخليط!","15","¼ كوب",
["1 بخّة (0.25 غرام) بخاخ طهي غير لاصق","2 ملعقة كبيرة بديل السكر البني قليل السعرات","⅛ ملعقة صغيرة فلفل كايين","1 كوب بذور اليقطين غير مملحة (نيئة، بيبيتاس)","1 كوب بذور عباد الشمس غير مملحة","1 كوب لوز شرائح غير مملح","¼ كوب بذور السمسم","1 أونصة توت أزرق مجفف بالتجميد"],
["سخّن الفرن مسبقًا إلى 300 درجة فهرنهايت (150 درجة مئوية).","رشّ صينية خبز ببخاخ الطهي غير اللاصق واتركها جانبًا.","في وعاء، اخلط بديل السكر البني وفلفل الكايين وبذور اليقطين وبذور عباد الشمس واللوز وبذور السمسم. قلّب لتتغطى المكونات.","افرد الخليط على صينية الخبز ثم رشّه مرة أخرى بطبقة خفيفة من بخاخ الطهي.","اخبزه لمدة 15 دقيقة، مع التقليب كل 5 دقائق لضمان التحمير المتساوي.","أخرجه من الفرن واتركه جانبًا ليبرد. وعندما يبرد، قلّب خليط المكسرات في وعاء مع التوت الأزرق المجفف بالتجميد."],[],[])))
O.append(R(6548283,
es=("Bol de yogur salado con algas y edamame","Este bol de yogur salado combina yogur griego cremoso sin grasa, edamame tierno y el crujiente salado de las algas tostadas para un refrigerio rico en proteínas y lleno de sabor. Es rápido, refrescante y ofrece un toque inspirado en el sushi sin necesidad de cocinar.","1","1 1/2 tazas",
["1 taza de yogur griego natural sin grasa","1 paquete de algas tostadas","1/2 taza de edamame sin cáscara"],
["Agregue 1 taza de yogur griego sin grasa a un tazón pequeño.","Agregue 1/2 taza de edamame sin cáscara y revuelva hasta que se distribuya de manera uniforme.","Desmenuce el paquete de algas tostadas por encima o incorpórelo a la mezcla para una textura más suave.","Sirva de inmediato para que las algas se mantengan crujientes."],[],[]),
ar=("وعاء زبادي مالح بالأعشاب البحرية والإدامامي","يجمع وعاء الزبادي المالح هذا بين الزبادي اليوناني الكريمي الخالي من الدسم والإدامامي الطري ومقرمشات الأعشاب البحرية المحمصة المالحة، لوجبة خفيفة غنية بالبروتين ومليئة بالنكهة. إنه سريع ومنعش ويمنحك لمسة مستوحاة من السوشي دون أي طهي.","1","1½ كوب",
["1 كوب زبادي يوناني سادة خالٍ من الدسم","1 كيس أعشاب بحرية محمصة","½ كوب إدامامي مقشر"],
["ضع 1 كوب من الزبادي اليوناني الخالي من الدسم في وعاء صغير.","أضف ½ كوب من الإدامامي المقشر وقلّب حتى يتوزع بالتساوي.","فتّت كيس الأعشاب البحرية المحمصة فوق الوعاء أو اخلطه به للحصول على قوام أنعم.","قدّمه فورًا لتبقى الأعشاب البحرية مقرمشة."],[],[])))
O.append(R(6548471,
ar=("أقراص الفاصولياء السوداء بالكزبرة والليمون الأخضر","هل تبحث عن برغر صيفي خفيف؟ أقراص الفاصولياء السوداء هذه لذيذة على خبز الحبوب الكاملة أو فوق السلطة أو ببساطة في طبق مع شرائح البصل.","10","1 قرص (4 أونصة)",
["1 ملعقة كبيرة زيت زيتون","1 كوب بصل (مفروم)","½ كوب فلفل رومي أخضر (مفروم)","½ كوب فلفل رومي أحمر (مفروم)","1 حبة فلفل هالابينو (مفرومة ناعمًا)","2 فص ثوم (مفروم)","1 ملعقة صغيرة مسحوق الفلفل الحار","½ ملعقة صغيرة أوريغانو مجفف","½ ملعقة صغيرة كمون مطحون","1 علبة فاصولياء سوداء قليلة الصوديوم (علبة 16 أونصة، لا تصفّها)","1 كوب فتات الخبز (غير متبّل)","¼ كوب دقيق الذرة الخشن، بالإضافة إلى كمية إضافية للتغبير (أصفر أو أبيض)","1 ملعقة كبيرة عصير ليمون أخضر","1 ملعقة صغيرة قشر ليمون أخضر مبشور","¾ ملعقة صغيرة ملح","¼ كوب جبن شيدر (قليل الدسم، أو استخدم جبن بيبر جاك قليل الدسم)","2 ملعقة كبيرة كزبرة خضراء (مفرومة ناعمًا)","1 بخّة (0.25 غرام) بخاخ طهي غير لاصق (للمغرفة أو كوب القياس)"],
["في مقلاة كبيرة غير لاصقة، سخّن زيت الزيتون وسوّط البصل والفلفل والثوم والتوابل. سوّطها لمدة 3 دقائق، أو حتى تصبح الخضار طرية.","أضف الفاصولياء السوداء مع سائلها وسوّطها مع الخضار لمدة دقيقة واحدة. ارفعها عن النار. أضف فتات الخبز ودقيق الذرة الخشن وعصير الليمون الأخضر وقشره والملح. أخرج 1 كوب من خليط الفاصولياء واهرسه في خلاط أو محضّرة طعام حتى تحصل على هريس خشن. أعد الهريس إلى خليط الفاصولياء بالطي. أضف جبن الشيدر والكزبرة الخضراء واخلط جيدًا. يجب أن يشبه الخليط عجينة خشنة وأن يكون متماسكًا بما يكفي ليثبت في المغرفة أو الملعقة.","باستخدام مغرفة الآيس كريم أو كوب قياس ⅓ كوب، شكّل حصصًا بوزن 3-4 أونصات. (رشّ مغرفة الآيس كريم أو كوب القياس برفق ببخاخ الطهي ليسهل إخراج الخليط). رشّ طبقًا بدقيق الذرة الخشن وضع عليه حصص الفاصولياء السوداء. غبّر خليط الفاصولياء السوداء برفق بدقيق الذرة الخشن واضغط عليه برفق لتشكيل قرص.","سخّن الفرن مسبقًا إلى 375 درجة فهرنهايت (190 درجة مئوية). رشّ مقلاة كبيرة غير لاصقة بالزيت النباتي. حمّر الأقراص لمدة دقيقتين من كل جانب. إذا كانت المقلاة مناسبة للفرن، فانقلها إلى الفرن واخبز لمدة 15 دقيقة أو حتى تسخن من الداخل. أو انقل الأقراص إلى صينية بسكويت واخبزها."],[],[])))
O.append(R(6549589,
es=("Crujiente de cerezas y avena","El crujiente de cerezas y avena es un postre delicioso que combina cerezas dulces y ácidas con una cobertura crujiente de avena. Esta versión más saludable es apta para personas con diabetes para que todos puedan disfrutarla.","6","1/2 taza",
["3 tazas de cerezas (frescas o congeladas, sin hueso)","1 cucharada de jugo de limón","3 cucharadas de sirope tipo maple sin azúcar","1 cucharadita de extracto de vainilla","3/4 de taza de avena en hojuelas tradicional","1/4 de taza de harina de almendra","1/4 de taza de nueces (picadas)","2 cucharadas de aceite vegetal (derretido)","1/4 de cucharadita de sal"],
["Precaliente el horno a 350 grados F. Cubra un molde para hornear de 9 x 9 pulgadas con papel pergamino.","En un tazón, mezcle las cerezas sin hueso, el jugo de limón, el sirope de maple sin calorías y el extracto de vainilla. Mezcle hasta que las cerezas queden bien cubiertas.","Agregue las cerezas al molde preparado y extiéndalas en una capa uniforme.","En otro tazón, mezcle la avena, la harina de almendra, las nueces picadas, el aceite vegetal y la sal. Revuelva hasta que la mezcla esté desmenuzada.","Espolvoree la mezcla de avena de manera uniforme sobre las cerezas.","Hornee durante unos 30 minutos o hasta que el relleno de cerezas burbujee y la cobertura de avena esté dorada.","Déjelo enfriar durante 10 minutos antes de servir.","Sirva tibio."],[],[]),
ar=("كرسبي الكرز والشوفان","كرسبي الكرز والشوفان حلوى رائعة تجمع بين الكرز الحلو والحامض مع طبقة علوية مقرمشة من الشوفان. هذه النسخة الأكثر صحة مناسبة لمرضى السكري ليتمكن الجميع من الاستمتاع بها.","6","½ كوب",
["3 كوب كرز (طازج أو مجمد، منزوع النوى)","1 ملعقة كبيرة عصير ليمون","3 ملعقة كبيرة شراب بنكهة القيقب خالٍ من السكر","1 ملعقة صغيرة خلاصة الفانيلا","¾ كوب شوفان مجروش تقليدي","¼ كوب دقيق اللوز","¼ كوب جوز (مفروم)","2 ملعقة كبيرة زيت نباتي (مذاب)","¼ ملعقة صغيرة ملح"],
["سخّن الفرن مسبقًا إلى 350 درجة فهرنهايت (175 درجة مئوية). بطّن طبق خبز مقاس 9 × 9 بوصات بورق الزبدة.","في وعاء، اخلط الكرز منزوع النوى وعصير الليمون وشراب القيقب الخالي من السعرات وخلاصة الفانيلا. قلّب حتى يتغطى الكرز جيدًا.","ضع الكرز في طبق الخبز المجهّز وافرده في طبقة متساوية.","في وعاء منفصل، اخلط الشوفان ودقيق اللوز والجوز المفروم والزيت النباتي والملح. قلّب حتى يصبح الخليط متفتتًا.","وزّع خليط الشوفان بالتساوي فوق الكرز.","اخبزه لمدة 30 دقيقة تقريبًا أو حتى تتبقع حشوة الكرز بالفقاعات ويصبح غطاء الشوفان ذهبي اللون.","اتركه يبرد لمدة 10 دقائق قبل التقديم.","قدّمه دافئًا."],[],[])))
O.append(R(6549802,
es=("Dip ahumado de frijoles negros","Sumérjase en un paraíso de sabor con nuestro dip ahumado de frijoles negros, una sensación vibrante que transforma los frijoles negros comunes en una fiesta ahumada. Sirva este dip con verduras frescas para un refrigerio o aperitivo saludable y bajo en carbohidratos, perfecto para personas con y sin diabetes.","6","1/4 de taza de dip + 1/2 taza de pepino y pimiento morrón en rodajas",
["1 lata (de 15 onzas) de frijoles negros (sin sal añadida, escurridos y enjuagados)","2 dientes de ajo (picados)","2 cucharadas de jugo de lima","1 cucharadita de comino molido","1/2 cucharadita de pimentón ahumado","1/2 cucharadita de sal","1/4 de cucharadita de pimienta negra","1 cucharada de aceite de oliva","2 cucharadas de yogur griego natural sin grasa","3 tazas de pepino (en rodajas)","3 tazas de pimiento morrón rojo (en rodajas)"],
["Use un procesador de alimentos para combinar los frijoles negros escurridos y enjuagados, el ajo picado, el cilantro fresco picado, el jugo de lima, el comino molido, el pimentón ahumado, la sal y la pimienta. Procese hasta obtener una consistencia suave y cremosa. Puede agregar poco a poco 1 cucharada de aceite de oliva mientras procesa para lograr la textura deseada. Ajuste la cantidad de aceite según su preferencia.","Después de procesar, pruebe el dip y haga los ajustes necesarios en los condimentos. Puede agregar más sal, pimienta o jugo de lima al gusto.","Pase el dip de frijoles negros a un tazón para servir y mezcle con suavidad 2 cucharadas de yogur griego natural. Este ingrediente aporta un toque cremoso y un poco de acidez al dip.","Sirva con rodajas de pepino y pimiento morrón."],[],[]),
ar=("غموس الفاصولياء السوداء المدخن","انغمس في جنة النكهات مع غموس الفاصولياء السوداء المدخن، وهو إحساس منعش يحوّل الفاصولياء السوداء العادية إلى احتفال مدخن. قدّم هذا الغموس مع خضار طازجة للحصول على وجبة خفيفة أو مقبلات صحية منخفضة الكربوهيدرات، مثالية للأشخاص المصابين بالسكري وغير المصابين به.","6","¼ كوب غموس + ½ كوب خيار وفلفل رومي مقطع إلى شرائح",
["1 علبة (15 أونصة) فاصولياء سوداء (بدون ملح مضاف، مصفاة ومشطوفة)","2 فص ثوم (مفروم)","2 ملعقة كبيرة عصير ليمون أخضر","1 ملعقة صغيرة كمون مطحون","½ ملعقة صغيرة بابريكا مدخنة","½ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","1 ملعقة كبيرة زيت زيتون","2 ملعقة كبيرة زبادي يوناني سادة خالٍ من الدسم","3 كوب خيار (مقطع إلى شرائح)","3 كوب فلفل رومي أحمر (مقطع إلى شرائح)"],
["استخدم محضّرة الطعام لخلط الفاصولياء السوداء المصفاة والمشطوفة والثوم المفروم والكزبرة الخضراء الطازجة المفرومة وعصير الليمون الأخضر والكمون المطحون والبابريكا المدخنة والملح والفلفل. اخلط حتى تحصل على قوام ناعم وكريمي. يمكنك أن تسكب 1 ملعقة كبيرة من زيت الزيتون تدريجيًا أثناء الخلط للحصول على القوام الذي تريده. عدّل كمية الزيت بحسب رغبتك.","بعد الخلط، تذوّق الغموس وأجرِ أي تعديلات لازمة على التوابل. يمكنك إضافة المزيد من الملح أو الفلفل أو عصير الليمون الأخضر بحسب ذوقك.","انقل غموس الفاصولياء السوداء إلى وعاء التقديم وأضف برفق 2 ملعقة كبيرة من الزبادي اليوناني السادة مع تحريكها على شكل دوامات. تمنح هذه الإضافة عنصرًا كريميًا ولمسة من الحموضة للغموس.","قدّمه مع شرائح الخيار والفلفل الرومي."],[],[])))
O.append(R(6549854,
ar=("فطر بورتوبيلو مشوي بالطماطم والأعشاب التوسكانية","يصنع هذا الفطر اللذيذ سندويشًا غنيًا بالنكهة بإضافة شريحة من الموزاريلا الطازجة أو البروفولون وتقديمه على خبز الحبوب الكاملة. قدّم معه سلطة خضروات ورقية مشكلة.","6","1 قبعة فطر",
["¼ كوب زيت زيتون بكر ممتاز","2 ملعقة كبيرة عصير ليمون","2 ملعقة كبيرة خل بلسمي","1 ملعقة كبيرة أوريغانو طازج (مفروم ناعمًا)","1 غصن إكليل الجبل الطازج (مفروم ناعمًا)","2 ملعقة كبيرة ريحان (مفروم ناعمًا)","2 فص ثوم (مفروم)","½ كوب طماطم (مفرومة)","½ ملعقة صغيرة فلفل أسود","6 حبات فطر بورتوبيلو كاملة (ممسوحة ومنزوعة السيقان)"],
["اخلط جميع مكونات التتبيلة في وعاء متوسط وضعها في كيس بلاستيكي كبير محكم الإغلاق. اترك قبعات الفطر لتتتبّل لمدة 15-30 دقيقة على الأقل في درجة حرارة الغرفة للحصول على أفضل النتائج.","سخّن الشواية مسبقًا على حرارة متوسطة عالية وضع قبعات الفطر على شبك الشواية. اشوِها على حرارة مباشرة لمدة 5 دقائق من كل جانب حتى تنضج تمامًا وتصبح طرية. افرد عليها المزيد من التتبيلة بالفرشاة من حين لآخر أثناء الطهي. يمكنك سكب أي تتبيلة متبقية فوق الفطر قبل التقديم."],[],[])))
O.append(R(6550239,
es=("Tortitas de pescado salteadas","El pescado blanco, el bacalao o la tilapia son pescados blancos de carne firme que sirven muy bien para preparar tortitas de pescado. La mostaza Dijon y el limón aportan un sabor fresco y ácido. Exprima un poco de jugo de limón por encima justo antes de servir para darle más chispa.","6","1 tortita",
["1 libra de pescado blanco (secado con toallas de papel y cortado en trozos)","1/4 de taza de yogur natural","1 cucharada de mostaza Dijon","1 cucharada de jugo de limón","1/2 cucharadita de sal","1 cucharadita de ralladura de limón","1 huevo grande (batido)","1 1/4 tazas de pan molido panko (dividido)","2 tallos de cebolleta (picados finos)","1/2 cucharadita de salsa picante","1 cucharada de aceite vegetal"],
["Agregue suficiente agua para llenar 2/3 de una sartén grande. A fuego medio, lleve el agua a punto de hervor suave. Agregue el pescado y cocine a fuego lento de 5 a 7 minutos, o hasta que esté bien cocido. Retire los trozos de pescado con una cuchara ranurada. Coloque el pescado en un tazón y déjelo enfriar durante 5 minutos.","Escurra el exceso de líquido del tazón. Agregue el yogur, la mostaza, el jugo de limón, la sal, la ralladura de limón y el huevo, y mezcle bien. Agregue 1/2 taza del pan molido y la cebolleta y la salsa picante, y mezcle bien. Forme 6 tortitas con la mezcla de pescado. Cubra ligeramente cada lado de las tortitas con el pan molido restante. Coloque las tortitas en un plato y refrigérelas, tapadas, durante 30 minutos.","Saque las tortitas del refrigerador y déjelas reposar 5 minutos. En una sartén grande, caliente el aceite a fuego medio. Agregue las tortitas a la sartén y saltee unos 5 minutos por lado, hasta que estén doradas."],[],[]),
ar=("كعكات السمك المسوّطة","السمك الأبيض أو سمك القد أو البلطي أنواع من الأسماك البيضاء متماسكة اللحم تصلح تمامًا لصنع كعكات السمك. يضيف خردل ديجون والليمون نكهة منعشة وحامضة. اعصر قليلًا من عصير الليمون فوقها قبل التقديم مباشرة لمزيد من الحيوية.","6","1 كعكة",
["1 رطل سمك أبيض (مجفف بالتربيت ومقطع إلى قطع)","¼ كوب زبادي سادة","1 ملعقة كبيرة خردل ديجون","1 ملعقة كبيرة عصير ليمون","½ ملعقة صغيرة ملح","1 ملعقة صغيرة قشر ليمون مبشور","1 بيضة كبيرة (مخفوقة)","1¼ كوب فتات خبز بانكو (يُستخدم على مرتين)","2 ساق بصل أخضر (مفرومة ناعمًا)","½ ملعقة صغيرة صلصة حارة","1 ملعقة كبيرة زيت نباتي"],
["املأ مقلاة كبيرة بالماء حتى ثلثيها. على حرارة متوسطة، اترك الماء حتى يصل إلى الغليان الهادئ. أضف السمك واتركه على نار هادئة لمدة 5 إلى 7 دقائق، أو حتى ينضج تمامًا. أخرج قطع السمك بملعقة مثقبة. ضع السمك في وعاء الخلط واتركه يبرد لمدة 5 دقائق.","صفِّ أي سائل زائد من الوعاء. أضف الزبادي والخردل وعصير الليمون والملح وقشر الليمون والبيض واخلط جيدًا. أضف ½ كوب من فتات الخبز مع البصل الأخضر والصلصة الحارة واخلط جيدًا. شكّل خليط السمك إلى 6 كعكات. غطِّ كل جانب من الكعكات برفق بفتات الخبز المتبقي. ضع الكعكات في طبق وضعها في الثلاجة مغطاة لمدة 30 دقيقة.","أخرج الكعكات من الثلاجة واتركها 5 دقائق. في مقلاة كبيرة، سخّن الزيت على حرارة متوسطة. ضع الكعكات في المقلاة وسوّطها لمدة 5 دقائق تقريبًا من كل جانب، حتى تصبح ذهبية اللون."],[],[])))
O.append(R(6550451,
es=("Ensalada verde con naranja, aguacate y cebolla","¡Sea creativo con sus naranjas! Pruebe las naranjas navel, Valencia, Cara Cara o sanguinas cuando las vea en su mercado local. Cada una tiene un sabor delicioso ligeramente distinto, pero todas están llenas de vitamina C, fibra y otros nutrientes que son buenos para usted. Complete su plato: agregue esta ensalada a cualquier comida que necesite un refuerzo de verduras. La hemos combinado con pastel de carne de pavo al estilo suroeste y puré de papas rojas.","4","1 1/2 tazas",
["1 cucharada de jugo de lima","1 cucharada de aceite de oliva","1 cucharadita de vinagre de vino tinto","1/8 de cucharadita de sustituto de azúcar bajo en calorías","1/4 de cucharadita de sal","1/8 de cucharadita de pimienta negra","2 naranjas medianas","4 tazas de mezcla de verduras de hoja verde","1 aguacate mediano (sin hueso y con la pulpa en cubos)","1/4 de cebolla morada pequeña (picada)","2 cucharadas de cilantro fresco (picado)"],
["En un tazón pequeño, bata el jugo de lima, el aceite de oliva, el vinagre de vino tinto, el edulcorante, la sal kosher y la pimienta negra.","Pele las naranjas y quíteles la parte blanca. Con un cuchillo pequeño, corte entre las membranas para sacar los gajos de naranja y córtelos en tercios. Coloque los trozos de naranja en un tazón mediano.","Agregue al tazón las verduras de hoja verde, los cubos de aguacate y la cebolla morada, y rocíe con la mezcla de jugo de lima. Mezcle para combinar. Espolvoree con el cilantro y sirva."],[],[]),
ar=("سلطة خضراء بالبرتقال والأفوكادو والبصل","كن مبدعًا مع البرتقال! جرّب برتقال السرة أو فالنسيا أو كارا كارا أو البرتقال الدموي عندما تراها في سوقك المحلي. لكل منها نكهة لذيذة مختلفة قليلًا، لكنها جميعًا مليئة بفيتامين C والألياف وغيرها من العناصر الغذائية المفيدة لك. أكمل طبقك: أضف هذه السلطة إلى أي وجبة تحتاج إلى دفعة من الخضار. وقد قدمناها مع رغيف لحم الديك الرومي على الطريقة الجنوبية الغربية وهريس البطاطس الحمراء.","4","1½ كوب",
["1 ملعقة كبيرة عصير ليمون أخضر","1 ملعقة كبيرة زيت زيتون","1 ملعقة صغيرة خل النبيذ الأحمر","⅛ ملعقة صغيرة بديل سكر قليل السعرات","¼ ملعقة صغيرة ملح","⅛ ملعقة صغيرة فلفل أسود","2 حبة برتقال متوسطة","4 كوب خضروات ورقية مشكلة","1 حبة أفوكادو متوسطة (منزوعة النواة ومقطعة اللب إلى مكعبات)","¼ حبة بصل أحمر صغيرة (مفرومة)","2 ملعقة كبيرة كزبرة خضراء طازجة (مفرومة)"],
["في وعاء صغير، اخفق عصير الليمون الأخضر وزيت الزيتون وخل النبيذ الأحمر والمحلّي وملح الكوشر والفلفل الأسود.","أزل القشر والجزء الأبيض من حول حبات البرتقال. باستخدام سكين صغيرة، اقطع بين الأغشية لتحرير فصوص البرتقال، وقطّعها إلى ثلاثة أجزاء. ضع قطع البرتقال في وعاء متوسط.","أضف الخضروات الورقية المشكلة ومكعبات الأفوكادو والبصل الأحمر إلى الوعاء ورشّ عليها خليط عصير الليمون الأخضر. قلّب لتمتزج المكونات. رشّ الكزبرة الخضراء وقدّم."],[],[])))
O.append(R(6551080,
es=("Camarones con chile y lima con salsa de poblano","Los camarones con chile y lima con salsa de poblano son un plato sabroso y vibrante que combina el picante de los chiles, la acidez de la lima y el sabor ahumado de los chiles poblanos.","6","1/4 de libra de camarones",
["1 chile poblano entero","3 dientes de ajo (divididos)","1/2 taza de yogur griego natural sin grasa","1 cucharadita de comino molido","1/8 de cucharadita de sal kosher","1 libra de camarones (pelados, dejando solo la cola, y desvenados)","1 cucharada de aceite de oliva","1 chile serrano entero (en rodajas)","1/4 de cucharadita de pimienta negra"],
["Cubra una bandeja para hornear con papel pergamino y precaliente el asador (broiler) a temperatura alta. Ase el chile poblano hasta que se ennegrezca ligeramente, unos 5 minutos, volteándolo un par de veces. Colóquelo en un tazón y tápelo con plástico para que se cueza al vapor durante 5 minutos.","Cuando esté lo suficientemente frío para tocarlo, retire la piel. Quite el tallo, abra el chile a lo largo para retirar las semillas y píquelo en trozos grandes.","Mezcle los camarones con 1/2 cucharada de aceite de oliva, 1 diente de ajo, los chiles y la pimienta. Déjelos marinar de 15 a 30 minutos.","Mientras los camarones se marinan, termine la salsa. Procese el chile poblano, el yogur griego, 2 dientes de ajo rallados, el comino, la sal kosher y la pimienta en un procesador de alimentos hasta que quede suave.","Caliente la 1/2 cucharada restante de aceite de oliva en una sartén. Cuando la sartén esté caliente, selle los camarones durante 2 minutos por lado, hasta que estén recién cocidos.","Sirva con la salsa de poblano."],[],[]),
ar=("روبيان بالفلفل الحار والليمون الأخضر مع صلصة البوبلانو","روبيان بالفلفل الحار والليمون الأخضر مع صلصة البوبلانو طبق غني بالنكهة ومنعش يجمع بين حرارة الفلفل وحموضة الليمون الأخضر ونكهة فلفل البوبلانو المدخنة.","6","¼ رطل روبيان",
["1 حبة فلفل بوبلانو كاملة","3 فص ثوم (يُستخدم على مرات)","½ كوب زبادي يوناني سادة خالٍ من الدسم","1 ملعقة صغيرة كمون مطحون","⅛ ملعقة صغيرة ملح كوشر","1 رطل روبيان (مقشر مع إبقاء الذيل ومنزوع الأمعاء)","1 ملعقة كبيرة زيت زيتون","1 حبة فلفل سيرانو كاملة (مقطعة إلى شرائح)","¼ ملعقة صغيرة فلفل أسود"],
["بطّن صينية خبز بورق الزبدة وسخّن الشواية العلوية مسبقًا على درجة عالية. اشوِ فلفل البوبلانو حتى يسودّ قليلًا، حوالي 5 دقائق، مع قلبه مرتين. ضعه في وعاء وغطِّه بغلاف بلاستيكي ليتبخر لمدة 5 دقائق.","عندما يبرد بما يكفي للمسه، قشّره. انزع الساق وافتح الفلفل بالشق لإزالة البذور، ثم قطّعه تقطيعًا خشنًا.","قلّب الروبيان مع ½ ملعقة كبيرة من زيت الزيتون وفص ثوم واحد والفلفل الحار والفلفل الأسود. اتركه ليتتبّل لمدة 15-30 دقيقة.","بينما يتتبّل الروبيان، أكمل الصلصة. اخلط فلفل البوبلانو والزبادي اليوناني وفصّي ثوم مبشورين والكمون وملح الكوشر والفلفل في محضّرة الطعام حتى يصبح ناعمًا.","سخّن ½ ملعقة كبيرة المتبقية من زيت الزيتون في مقلاة. عندما تسخن المقلاة، احمّر الروبيان لمدة دقيقتين من كل جانب حتى ينضج بالكاد.","قدّمه مع صلصة البوبلانو."],[],[])))
